import csv
from io import StringIO


def rollup_sales(csv_text: str) -> list[tuple[str, int]]:
    if not csv_text.strip():
        return []

    reader = csv.DictReader(StringIO(csv_text))

    # Check if header exists and has required columns
    if reader.fieldnames is None or 'region' not in reader.fieldnames:
        return []

    totals = {}

    for row in reader:
        # Skip blank rows (rows with missing critical fields)
        if not row.get('region') or not row.get('item'):
            continue

        try:
            quantity = int(row['quantity'])
        except ValueError:
            continue

        region = row['region']

        totals[region] = totals.get(region, 0) + quantity

    return sorted(totals.items())

