from typing import List, Tuple


def detect_spikes(values: list[float], width: int, threshold: float) -> list[tuple[int, float]]:
    if not isinstance(values, list) or not isinstance(width, int) or not isinstance(threshold, (int, float)):
        return []

    if len(values) == 0 or width <= 0 or threshold <= 0:
        return []

    if len(values) < width + 1:
        return []

    result = []

    for i in range(width, len(values)):
        baseline_start = i - width
        baseline_end = i

        window_values = values[baseline_start:baseline_end]

        if not window_values:
            continue

        avg = sum(window_values) / len(window_values)

        if values[i] > avg * threshold:
            rounded_avg = round(avg, 2)
            result.append((i, rounded_avg))

    return result

