from typing import Any


def flatten_json(value: Any) -> dict[str, object]:
    """
    Flatten nested dictionaries and lists into path keys.

    Dictionary keys are joined with dots. List indexes use square brackets.
    Examples: user.name, user.tags[0], orders[1].total.
    Only scalar leaves are stored, but empty dictionaries and empty lists are leaves too.
    If the root value is scalar, return {"": value}.
    Process dictionary keys in sorted order for deterministic output.
    """
    result: dict[str, object] = {}

    def walk(node: Any, path: str):
        # Handle empty containers as leaves immediately to avoid recursion issues
        if node == {}:
            result[path] = {}
            return
        if node == []:
            result[path] = []
            return

        if isinstance(node, dict):
            # Sort keys for deterministic output
            for key in sorted(node.keys()):
                child_path = f"{path}.{key}" if path else str(key)
                walk(node[key], child_path)

        elif isinstance(node, list):
            for i, item in enumerate(node):
                item_path = f"{path}[{i}]" if path else f"[{i}]"
                walk(item, item_path)

        else:
            # Scalar or empty container that wasn't caught above (though {} and [] are handled)
            # Note: The prompt says "Only scalar leaves are stored, but empty dictionaries 
            # and empty lists are leaves too." Since we handle {} and [] explicitly at the top,
            # any remaining non-dict/non-list is a scalar.
            result[path] = node

    if isinstance(value, dict):
        walk(value, "")
    elif isinstance(value, list):
        walk(value, "")
    else:
        # Root value is scalar
        result[""] = value

    return result

