from collections import defaultdict


def topo_batches(edges: list[tuple[str, str]]) -> list[list[str]]:
    # Build adjacency list and in-degree count
    graph = defaultdict(list)
    indegree = {}

    all_nodes = set()

    for before, after in edges:
        all_nodes.add(before)
        all_nodes.add(after)
        graph[before].append(after)
        indegree[after] = indegree.get(after, 0) + 1

    # Ensure all nodes have an entry in indegree (even if 0)
    for node in all_nodes:
        if node not in indegree:
            indegree[node] = 0

    # Initialize available nodes (indegree == 0)
    available = []
    for node in sorted(all_nodes):
        if indegree[node] == 0:
            available.append(node)

    batches = []

    while available:
        # Sort available nodes to ensure deterministic order within the batch
        current_batch = sorted(available)
        batches.append(current_batch)

        next_available = []
        for node in current_batch:
            neighbors = graph[node]
            for neighbor in neighbors:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    next_available.append(neighbor)

        available = next_available

    # If no nodes were processed but there were nodes, it implies a cycle (or empty input handled above)
    # However, the loop condition handles empty input. 
    # If we started with nodes and finished without adding them to batches, it means a cycle existed.
    if not batches and all_nodes:
        return []

    return batches

