def deep_merge(base: dict, override: dict) -> dict:
    """
    Recursively merges two dictionaries.

    - If both values are dicts, they are merged recursively.
    - Otherwise, the value from `override` replaces the one in `base`.
    - If an override value is None, that key is deleted from the result (if it exists).
    - New keys in `override` with non-None values are added to the result.
    - The function does not mutate `base` or `override`.

    Args:
        base (dict): The base dictionary.
        override (dict): The overriding dictionary.

    Returns:
        dict: A new merged dictionary.
    """
    # Start with a copy of the base dictionary to avoid mutation and preserve structure.
    result = {}

    # Step 1: Copy all keys from `base`.
    # For nested dictionaries, we must copy them recursively to ensure deep copying 
    # (or at least structural independence) before applying overrides.
    for key in base:
        val_base = base[key]
        if isinstance(val_base, dict):
            result[key] = _deep_copy_dict(val_base)
        else:
            result[key] = val_base

    # Step 2: Process keys from `override`.
    for key, val_override in override.items():
        if key not in result:
            # Key exists only in override.
            # If the value is None, we skip it (do nothing).
            # Otherwise, add it to the result.
            if val_override is None:
                continue
            else:
                # If it's a dict, copy it; otherwise assign directly.
                if isinstance(val_override, dict):
                    result[key] = _deep_copy_dict(val_override)
                else:
                    result[key] = val_override
        else:
            # Key exists in both base and override.
            val_base = result[key]  # Use the value from our constructed result

            if isinstance(val_base, dict) and isinstance(val_override, dict):
                # Both are dicts: merge recursively.
                merged = deep_merge(val_base, val_override)
                result[key] = merged
            else:
                # Not both dicts (or one is None). 
                # If override value is None, delete the key from result.
                if val_override is None:
                    del result[key]
                else:
                    # Otherwise, replace with override value.
                    if isinstance(val_override, dict):
                        result[key] = _deep_copy_dict(val_override)
                    else:
                        result[key] = val_override

    return result


def _deep_copy_dict(d: dict) -> dict:
    """Helper to recursively copy a dictionary."""
    if not isinstance(d, dict):
        raise TypeError("Expected dict")

    # Create a new empty dict
    copied = {}
    for k, v in d.items():
        if isinstance(v, dict):
            copied[k] = _deep_copy_dict(v)
        else:
            copied[k] = v
    return copied

