use std::io::{self, BufRead};
use rust_ordo_ext::{Scheduler, Plan};

fn main() {
    let mut scheduler = Scheduler::new();
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }
        match parts[0] {
            "node" => {
                let name = parts[1];
                let cost = parts[2].parse::<u32>().unwrap();
                let capacity = parts[3].parse::<u32>().unwrap();
                scheduler.add_node(name, cost, capacity);
            }
            "ramp" => {
                let from = parts[1];
                let to = parts[2];
                scheduler.add_ramp(from, to);
            }
            "schedule" => {
                let task_id = parts[1];
                let max_cost = parts[2].parse::<u32>().unwrap();
                let candidates: Vec<&str> = parts.iter().skip(3).take(parts.len() - 3).copied().collect();
                if let Some(plan) = scheduler.schedule(task_id, &candidates, max_cost) {
                    println!(
                        "task={} node={} promoted={} signals={}",
                        plan.task_id,
                        plan.node,
                        plan.promoted,
                        if plan.signals.is_empty() {
                            "none".to_string()
                        } else {
                            plan.signals.join(",")
                        }
                    );
                }
            }
            _ => {}
        }
    }
}
