#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RampTrace {
    pub path: Vec<String>,
    pub elevations: Vec<String>,
    pub promotions: usize,
    pub demotions: usize,
}

pub struct RampRuntime {
    edges: Vec<(String, String)>,
    states: std::collections::HashMap<String, String>,
}

impl RampRuntime {
    pub fn new() -> Self {
        RampRuntime {
            edges: Vec::new(),
            states: std::collections::HashMap::new(),
        }
    }

    pub fn on_ramp(&mut self, from: &str, to: &str) {
        self.edges.push((from.to_string(), to.to_string()));
        self.states.insert(to.to_string(), "parallel".to_string());
    }

    pub fn off_ramp(&mut self, from: &str, to: &str) {
        self.edges.push((from.to_string(), to.to_string()));
        self.states.insert(to.to_string(), "local".to_string());
    }

    pub fn trace(&self, start: &str) -> RampTrace {
        let mut promotions = 0;
        let mut demotions = 0;

        let mut current_node = start.to_string();
        let mut current_state = self.states.get(&current_node).cloned().unwrap_or_else(|| "local".to_string());

        let mut path = vec![current_node.clone()];
        let mut elevations = vec![current_state.clone()];

        while let Some((_, to)) = self.edges.iter().find(|(from, _)| from == &current_node) {
            let next_node = to.clone();
            let next_state = self.states.get(&next_node).cloned().unwrap_or_else(|| "local".to_string());

            if current_state == "local" && next_state == "parallel" {
                promotions += 1;
            } else if current_state == "parallel" && next_state == "local" {
                demotions += 1;
            }

            path.push(next_node.clone());
            elevations.push(next_state.clone());

            current_node = next_node;
            current_state = next_state;
        }

        RampTrace {
            path,
            elevations,
            promotions,
            demotions,
        }
    }
}
