use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RetryPlan {
    pub task_id: String,
    pub node: String,
    pub signals: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryRuntime {
    nodes: HashMap<String, bool>,
}

impl RetryRuntime {
    pub fn new() -> Self {
        RetryRuntime {
            nodes: HashMap::new(),
        }
    }

    pub fn add_node(&mut self, name: &str, healthy: bool) {
        self.nodes.insert(name.to_string(), healthy);
    }

    pub fn plan(&self, task_id: &str, candidates: &[&str]) -> Option<RetryPlan> {
        let mut signals = Vec::new();

        for &candidate in candidates {
            match self.nodes.get(candidate) {
                Some(true) => {
                    return Some(RetryPlan {
                        task_id: task_id.to_string(),
                        node: candidate.to_string(),
                        signals,
                    });
                }
                Some(false) | None => {
                    signals.push(format!("retry:{}", candidate));
                }
            }
        }

        None
    }
}
