fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut runtime = RetryRuntime::new();
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let line = line?;
        if line.is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        match parts.as_slice() {
            ["node", name, "healthy"] => {
                runtime.add_node(name, true);
            }
            ["node", name, "failed"] => {
                runtime.add_node(name, false);
            }
            ["plan", task_id, candidates @ ..] => {
                if let Some(plan) = runtime.plan(task_id, candidates) {
                    let signals_str = if plan.signals.is_empty() {
                        String::from("none")
                    } else {
                        plan.signals.join(",")
                    };
                    println!("task={} node={} signals={}", plan.task_id, plan.node, signals_str);
                }
            }
            _ => {}
        }
    }

    Ok(())
}
