    }

    pub fn serialize(&self) -> String {
        if self.edges.is_empty() {
            return String::new();
        }
        let serialized: Vec<String> = self
            .edges
            .iter()
            .map(|(f, t)| format!("{}>{}", f, t))
            .collect();
        serialized.join(";")
    }

