        let mut edges: Vec<(String, String)> = Vec::new();
        for part in dsl.split(';') {
            if let Some((from, to)) = part.split_once('>') {
                edges.push((from.to_string(), to.to_string()));
            }
        }
        Workflow { edges }
    }

    pub fn edges(&self) -> &[(String, String)] {
        &self.edges
    }
}
