use std::io::{self, BufRead};
use rust_ordo_ext::FanoutJoin;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let fj = FanoutJoin::new();
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let line = line?;
        if line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        match parts.as_slice() {
            ["fanout", source, targets @ ..] => {
                let target_refs: Vec<&str> = targets.iter().map(|&s| s).collect();
                let result = fj.fanout(source, &target_refs);
                println!("fanout={}", result.join(","));
            }
            ["join", pairs @ ..] => {
                let mut pair_list = Vec::new();
                for pair in pairs {
                    if let Some((key, value)) = pair.split_once('=') {
                        pair_list.push((key, value));
                    }
                }
                println!("joined={}", fj.join(&pair_list));
            }
            _ => {}
        }
    }
    Ok(())
}
